import contextlib
import logging
import ssl
import typing

import websockets
import websockets.client
import websockets.exceptions
import websockets.server

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.base import IClosable

from . import _globals, exc
from ._endpoint import Endpoint, dump_to_url
from .acceptor import ForwardingAcceptor
from .interface import IReactor, IStream, ITask
from .streams import QueueReadOnlyStream

logger = logging.getLogger(_globals.LOGGER_NAME)


class WSServer(IClosable):

    def __init__(self, reactor: IReactor, forwarder: ForwardingAcceptor):
        self._reactor = reactor
        self._forwarder = forwarder
        self._closed = False
        self._server_task: ITask = None

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.info('Web Socket server closing started...')
            if self._server_task is not None:
                await self._server_task.cancel()
            logger.info('Web Socket server closed.')

    async def bind(self, endpoint: Endpoint):

        async def do_bind():

            @_utils.log_exceptions(logger)
            async def handle_connection(websocket: websockets.server.WebSocketServerProtocol, *args):
                logger.info('Web Socket connection accepted from %r', websocket.remote_address)
                stream = _WSStream(self._reactor, websocket)
                with contextlib.suppress(websockets.exceptions.ConnectionClosedError):
                    async with stream:
                        self._forwarder.dispatch(stream)
                        async for data in websocket:
                            stream.data_received(data)
                logger.info('Web Socket connection lost')

            @_utils.log_exceptions(logger)
            async def serve_forever():

                async def run():
                    async with server:
                        await asyncio.Future()

                async def run_py36():
                    try:
                        await asyncio.Future()
                    finally:
                        server.close()
                        await server.wait_closed()

                logger.info('Web Socket server is running at %s', dump_to_url(endpoint))
                if _utils.python_version_gt(3, 6):
                    await run()
                else:
                    await run_py36()

            ssl_context = None
            host, port = endpoint.netloc.require_host_port()
            if endpoint.scheme == 'wss':
                ssl_context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
                ssl_context.load_cert_chain(endpoint.query['certfile'][0], keyfile=endpoint.query['keyfile'][0])
            server = await websockets.serve(
                handle_connection, host, port, ssl=ssl_context, ping_interval=None, max_size=None
            )
            self._server_task = self._reactor.run(serve_forever())

        try:
            await do_bind()
        except Exception as e:
            raise exc.BindFailedError(f"Couldn't bind a Web Socket server to {dump_to_url(endpoint)}", original_exc=e)


class WSClient(IClosable):

    def __init__(self, reactor: IReactor):
        self._reactor = reactor
        self._closed = False
        self._active_connections: typing.Dict[int, IClosable] = {}

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.info('Web Socket client closing started...')
            for connection in dict(self._active_connections).values():
                await connection.close()
            logger.info('Web Socket client closed.')

    async def connect(self, endpoint: Endpoint) -> IStream:

        async def do_connect():
            ssl_context = None
            if endpoint.scheme == 'wss':
                ssl_context = ssl.create_default_context(ssl.Purpose.SERVER_AUTH)
                if endpoint.query and endpoint.query.getfirst('no_cert_validation') == '1':
                    ssl_context.check_hostname = False
                    ssl_context.verify_mode = ssl.CERT_NONE
            endpoint_url = dump_to_url(endpoint)
            websocket = await websockets.connect(endpoint_url, ssl=ssl_context, max_size=None)
            logger.info('Web Socket client is connected with %s', endpoint_url)
            return self._ClientConnection(self, websocket)

        try:
            return await do_connect()
        except OSError as e:
            raise exc.ConnectFailedError(
                f"Couldn't establish a Web Socket connection with {dump_to_url(endpoint)}", original_exc=e
            )

    class _ClientConnection(IStream):

        def __init__(self, creator: 'WSClient', websocket: websockets.client.WebSocketClientProtocol):

            @_utils.log_exceptions(logger)
            async def reader():
                async with self._target:
                    with contextlib.suppress(websockets.exceptions.ConnectionClosedError):
                        async for data in websocket:
                            self._target.data_received(data)

            self._id = _utils.next_unique_id(self.__class__)
            self._creator = creator
            self._closed = False
            self._target = _WSStream(creator._reactor, websocket)
            self._reader_task = creator._reactor.run(reader())
            creator._active_connections[self._id] = self

        def is_closed(self) -> bool:
            return self._closed

        async def close(self):
            if not self._closed:
                self._closed = True
                del self._creator._active_connections[self._id]
                await self._target.close()
                await self._reader_task.cancel()

        async def read(self, count: int) -> bytes:
            return await self._target.read(count)

        async def write(self, data: bytes) -> int:
            return await self._target.write(data)

        def get_write_buffer_size(self) -> int:
            return self._target.get_write_buffer_size()


class _WSStream(IStream):

    def __init__(self, reactor: IReactor, websocket: websockets.client.WebSocketClientProtocol):
        self._websocket = websocket
        self._closed = False
        self._read_buffer = b''
        self._incoming_data_queue = asyncio.Queue()
        self._input_stream = QueueReadOnlyStream(self._incoming_data_queue)

    def data_received(self, data: bytes):
        self._incoming_data_queue.put_nowait(data)

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            await self._input_stream.close()
            await self._websocket.close()

    async def read(self, count: int) -> bytes:
        return await self._input_stream.read(count)

    async def write(self, data: bytes) -> int:
        try:
            await self._websocket.send(data)
        except websockets.exceptions.ConnectionClosed:
            raise exc.StreamClosedError()
        return len(data)

    def get_write_buffer_size(self) -> int:
        return self._websocket.transport.get_write_buffer_size()
